ALTER TABLE content_revisions DROP CONSTRAINT revision_numbers;
ALTER TABLE content_revisions ADD CONSTRAINT revision_numbers CHECK(version_number>0 AND ((revision_kind='PUBLISHED' AND published_edition_number IS NOT NULL AND published_edition_number>0) OR (revision_kind='MANUAL_SNAPSHOT' AND published_edition_number IS NULL)));
ALTER TABLE media DROP CONSTRAINT media_values;
ALTER TABLE media ADD CONSTRAINT media_values CHECK(storage_provider='S3' AND mime_type IN ('image/jpeg','image/png','image/webp') AND size_bytes>0 AND checksum_sha256 ~ '^[a-f0-9]{64}$' AND ((width IS NULL AND height IS NULL) OR (width IS NOT NULL AND height IS NOT NULL AND width>0 AND height>0)) AND processing_status IN ('UPLOADING','PROCESSING','READY','FAILED') AND (processing_status<>'READY' OR (width IS NOT NULL AND height IS NOT NULL)) AND (NOT capture_time_trusted OR captured_at IS NOT NULL));
ALTER TABLE idempotency_records DROP CONSTRAINT idempotency_values;
ALTER TABLE idempotency_records ADD CONSTRAINT idempotency_values CHECK(status IN ('PROCESSING','COMPLETED','FAILED') AND request_hash ~ '^[a-f0-9]{64}$' AND expires_at>created_at AND (status<>'COMPLETED' OR (response_status IS NOT NULL AND response_status BETWEEN 200 AND 599 AND response_reference IS NOT NULL)));
ALTER TABLE backup_runs ADD CONSTRAINT backup_terminal CHECK(status<>'SUCCEEDED' OR (checksum IS NOT NULL AND size_bytes IS NOT NULL AND started_at IS NOT NULL));
CREATE FUNCTION ps_search_text(v text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT btrim(regexp_replace(normalize(COALESCE(v,''),NFKC),'[[:space:]]+',' ','g')) $$;
CREATE OR REPLACE FUNCTION ps_check_content() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE cid uuid; c contents%ROWTYPE; r content_revisions%ROWTYPE; pub content_publications%ROWTYPE; BEGIN
 IF TG_TABLE_NAME='contents' THEN cid=COALESCE(NEW.id,OLD.id); ELSE cid=COALESCE(NEW.content_id,OLD.content_id); END IF;
 SELECT * INTO c FROM contents WHERE id=cid; IF NOT FOUND THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM content_drafts WHERE content_id=cid) THEN RAISE EXCEPTION 'content draft missing' USING ERRCODE='23514'; END IF;
 IF c.published_revision_id IS NOT NULL THEN
  SELECT * INTO r FROM content_revisions WHERE content_id=cid AND id=c.published_revision_id; IF NOT FOUND OR r.revision_kind<>'PUBLISHED' THEN RAISE EXCEPTION 'publication must point to published own revision' USING ERRCODE='23514'; END IF;
  SELECT * INTO pub FROM content_publications WHERE content_id=cid; IF NOT FOUND OR pub.revision_id<>r.id OR pub.title<>r.snapshot->>'title' OR pub.summary IS DISTINCT FROM r.snapshot->>'summary' OR pub.category_id::text IS DISTINCT FROM r.snapshot->>'categoryId' OR pub.cover_media_id::text IS DISTINCT FROM r.snapshot->>'coverMediaId' OR pub.published_at IS DISTINCT FROM c.last_published_at THEN RAISE EXCEPTION 'publication projection mismatch' USING ERRCODE='23514'; END IF;
  IF (SELECT count(*) FROM content_routes WHERE content_id=cid AND route_kind='CANONICAL')<>1 THEN RAISE EXCEPTION 'canonical route missing' USING ERRCODE='23514'; END IF;
  PERFORM ps_assert_projection(r.snapshot,cid,'publication');
  IF EXISTS(SELECT 1 FROM content_media x JOIN media m ON m.id=x.media_id WHERE x.content_id=cid AND (m.processing_status<>'READY' OR m.deleted_at IS NOT NULL)) THEN RAISE EXCEPTION 'publication media not ready' USING ERRCODE='23514'; END IF;
 ELSE IF EXISTS(SELECT 1 FROM content_publications WHERE content_id=cid) THEN RAISE EXCEPTION 'unpublished initial content has publication' USING ERRCODE='23514'; END IF; END IF;
 IF c.publication_state='PUBLISHED' AND c.effective_visibility='PUBLIC' AND c.deleted_at IS NULL THEN IF NOT EXISTS(SELECT 1 FROM content_search_documents WHERE content_id=cid AND revision_id=c.published_revision_id) THEN RAISE EXCEPTION 'public search projection missing' USING ERRCODE='23514'; END IF;
 ELSE IF EXISTS(SELECT 1 FROM content_search_documents WHERE content_id=cid) THEN RAISE EXCEPTION 'nonpublic search projection present' USING ERRCODE='23514'; END IF; END IF;
 IF c.publication_state='PUBLISHED' AND c.effective_visibility='PUBLIC' AND c.deleted_at IS NULL AND EXISTS(SELECT 1 FROM content_search_documents d WHERE d.content_id=cid AND (d.title IS DISTINCT FROM ps_search_text(r.snapshot->>'title') OR d.summary IS DISTINCT FROM ps_search_text(r.snapshot->>'summary') OR d.searchable_text IS DISTINCT FROM ps_search_text(r.snapshot->>'bodyMarkdown') OR d.module<>c.module OR d.content_type<>c.type OR d.published_at IS DISTINCT FROM c.last_published_at OR d.category_text IS DISTINCT FROM (SELECT ps_search_text(cat.name) FROM (SELECT 1) x LEFT JOIN categories cat ON cat.id::text=r.snapshot->>'categoryId') OR d.tags_text IS DISTINCT FROM (SELECT COALESCE(string_agg(ps_search_text(t.name),' ' ORDER BY ids.n),'') FROM jsonb_array_elements_text(r.snapshot->'tagIds') WITH ORDINALITY ids(id,n) JOIN tags t ON t.id::text=ids.id))) THEN RAISE EXCEPTION 'search text projection mismatch' USING ERRCODE='23514'; END IF;
 RETURN NULL; END $$;
